pub fn get_triple<T: PartialEq>(a: &[T]) -> usize {
    // If there are fewer than 3 elements, we cannot have a triple.
    if a.len() < 3 {
        return a.len();
    }

    // Scan from i = 0 up to i = len - 3 (inclusive), checking a[i], a[i+1], a[i+2]
    // for equality.
    let upper = a.len() - 2;
    for i in 0..upper {
        if a[i] == a[i + 1] && a[i] == a[i + 2] {
            return i;
        }
    }

    // No triple found
    a.len()
}

